mapper.select:
  select m.*,ha.END_TIME_ as end_time from (
    select a.id,a.act_id,a.user_name,c.depart_name,'punch' apply_typ,a.punch_date apply_date,'-' apply_day,a.create_time from tb_punch a
    left join tb_staff b on (a.user_id=b.staff_id)
    left join tb_depart c on (b.depart_id = c.depart_id)
    where a.status in ('97','99')
    AND b.delete_flag != 1

      and a.user_name like concat('%',#{userName,jdbcType=VARCHAR},'%')


      and a.punch_date >= #{beginDate,jdbcType=VARCHAR}


      and a.punch_date <= #{endDate,jdbcType=VARCHAR}


        and c.depart_name = #{departName,jdbcType=VARCHAR}

  union all
  select a.id,a.act_id,a.user_name,c.depart_name,'over' apply_typ,a.over_date apply_date,a.over_day apply_day,a.create_time from tb_over a
  left join tb_staff b on (a.user_id=b.staff_id)
  left join tb_depart c on (b.depart_id = c.depart_id)
  where a.status in ('97','99')
  AND b.delete_flag != 1

    and a.user_name like concat('%',#{userName,jdbcType=VARCHAR},'%')


    and a.over_date >= #{beginDate,jdbcType=VARCHAR}


    and a.over_date <= #{endDate,jdbcType=VARCHAR}


     and c.depart_name = #{departName,jdbcType=VARCHAR}

  union all
  select a.id,a.act_id,a.user_name,c.depart_name,'out' apply_typ,a.out_date apply_date,a.out_day apply_day,a.create_time from tb_out a
  left join tb_staff b on (a.user_id=b.staff_id)
  left join tb_depart c on (b.depart_id = c.depart_id)
  where a.status in ('97','99')
  AND b.delete_flag != 1

    and a.user_name like concat('%',#{userName,jdbcType=VARCHAR},'%')


    and a.out_date >= #{beginDate,jdbcType=VARCHAR}


    and a.out_date <= #{endDate,jdbcType=VARCHAR}


     and c.depart_name = #{departName,jdbcType=VARCHAR}

union all
  select a.id,a.act_id,a.user_name,c.depart_name,'trip1' apply_typ,concat(a.trip_date,'至',a.back_date) apply_date,a.trip_day apply_day,a.create_time from tb_trip a
  left join tb_staff b on (a.user_id=b.staff_id)
  left join tb_depart c on (b.depart_id = c.depart_id)
  where a.status in ('99')
  AND b.delete_flag != 1

    and a.user_name like concat('%',#{userName,jdbcType=VARCHAR},'%')


    and a.trip_date >= #{beginDate,jdbcType=VARCHAR}


    and a.trip_date <= #{endDate,jdbcType=VARCHAR}


     and c.depart_name = #{departName,jdbcType=VARCHAR}

    union all
    select a.id,a.act_id,a.user_name,c.depart_name,'trip2' apply_typ,concat(a.trip_date,'至',a.back_date) apply_date,a.trip_day apply_day,a.create_time from tb_trip a
    left join tb_staff b on (a.user_id=b.staff_id)
    left join tb_depart c on (b.depart_id = c.depart_id)
    where a.status in ('97','98')
    AND b.delete_flag != 1

        and a.user_name like concat('%',#{userName,jdbcType=VARCHAR},'%')


        and a.trip_date >= #{beginDate,jdbcType=VARCHAR}


        and a.trip_date <= #{endDate,jdbcType=VARCHAR}


        and c.depart_name = #{departName,jdbcType=VARCHAR}

  union all
  select a.id,a.act_id,a.user_name,c.depart_name,'vacation' apply_typ,concat(a.leave_date,'至',a.back_date) apply_date,a.leave_day apply_day,a.create_time
  from tb_vacation a left join tb_staff b on (a.user_id=b.staff_id)
  left join tb_depart c on (b.depart_id = c.depart_id)
  where a.status in ('97','98','99')
  AND b.delete_flag != 1

    and a.user_name like concat('%',#{userName,jdbcType=VARCHAR},'%')


    and a.leave_date >= #{beginDate,jdbcType=VARCHAR}


    and a.leave_date <= #{endDate,jdbcType=VARCHAR}


     and c.depart_name = #{departName,jdbcType=VARCHAR}

  union all
  select a.id,a.act_id,a.user_name,c.depart_name,'down' apply_typ,a.create_time apply_date,'-' apply_day,a.create_time from tb_down a
  left join tb_staff b on (a.user_id=b.staff_id)
  left join tb_depart c on (b.depart_id = c.depart_id)
  where a.status in ('97','99')
  AND b.delete_flag != 1

    and a.user_name like concat('%',#{userName,jdbcType=VARCHAR},'%')


    and a.create_time >= #{beginDate,jdbcType=VARCHAR}


    and a.create_time <= #{endDate,jdbcType=VARCHAR}


    and c.depart_name = #{departName,jdbcType=VARCHAR}

  ) m LEFT JOIN act_hi_actinst ha on m.act_id = ha.PROC_INST_ID_
  where 1=1
  and ha.ACT_TYPE_ = 'endEvent'

    and apply_typ = #{applyTyp,jdbcType=VARCHAR}

  order by ha.END_TIME_ desc

select m.* from (
select a.id,a.act_id,a.user_name,c.depart_name,'punch' apply_typ,a.punch_date apply_date,'-' apply_day,a.create_time from tb_punch a
left join tb_staff b on (a.user_id=b.staff_id)
left join tb_depart c on (b.depart_id = c.depart_id)
where a.status in ('01')
AND b.delete_flag != 1

    and a.user_name like concat('%',#{userName,jdbcType=VARCHAR},'%')


    and a.punch_date >= #{beginDate,jdbcType=VARCHAR}


    and a.punch_date <= #{endDate,jdbcType=VARCHAR}


    and c.depart_name = #{departName,jdbcType=VARCHAR}

union all
select a.id,a.act_id,a.user_name,c.depart_name,'over' apply_typ,a.over_date apply_date,a.over_day apply_day,a.create_time from tb_over a
left join tb_staff b on (a.user_id=b.staff_id)
left join tb_depart c on (b.depart_id = c.depart_id)
where a.status in ('01')
AND b.delete_flag != 1

